// Convert dotted Feature and Module names into browsable folders without changing object IDs.
function placeNamespaceObject(p,o){
 if(!['feature','module'].includes(o.group)||o.kind==='Category'||!o.name.includes('.'))return [];
 const parts=o.name.split('.').map(part=>part.trim());if(parts.some(part=>!part))return [];
 let parent=o.parent||null;const created=[];
 for(const part of parts.slice(0,-1)){
  let folder=p.objects.find(item=>item.group===o.group&&item.kind==='Category'&&(item.parent||null)===parent&&item.name.toLowerCase()===part.toLowerCase());
  if(!folder){folder={id:uid(),name:part,kind:'Category',icon:'▱',group:o.group,parent,description:'',owner:'ProjectPack'};p.objects.push(folder);created.push(folder)}
  parent=folder.id;
 }
 o.name=parts.at(-1);o.parent=parent;return created;
}
for(const p of [...db.projects,...Object.values(db.packProjects||{})]){
 if(p.namespaceFoldersV1)continue;p.saved??={};p.confirmed??={};
 for(const o of [...p.objects]){
  if(!['feature','module'].includes(o.group)||o.kind==='Category'||!o.name.includes('.'))continue;
  const folders=placeNamespaceObject(p,o);
  for(const folder of folders){p.saved[folder.id]=structuredClone(folder);p.confirmed[folder.id]=structuredClone(folder)}
  for(const baseline of [p.saved,p.confirmed])if(baseline[o.id]){baseline[o.id].name=o.name;baseline[o.id].parent=o.parent}
 }
 p.namespaceFoldersV1=true;
}persist();
