function openRunViewport(){const w=openWindow('run','실행 화면',502,348);w.body.innerHTML=`<div class="run-viewport"><div class="run-controls"><button type="button" data-run-play aria-label="재생" title="재생">▶</button><button type="button" data-run-pause aria-label="일시정지" title="일시정지">Ⅱ</button><button type="button" data-run-step aria-label="다음 프레임" title="다음 프레임">▸│</button><span class="run-status"></span></div><div class="run-screen"><div class="run-scene"><div class="run-horizon"></div><div class="run-entity">◉</div><strong>${esc(project.name)}</strong><small>Prototype 렌더 화면</small></div><span class="run-frame"></span></div></div>`;const refresh=()=>{w.body.querySelector('.run-status').textContent=running?(runPaused?'일시정지':'재생 중'):'대기';w.body.querySelector('.run-frame').textContent='FRAME '+(project.runFrame||0);w.body.querySelector('.run-scene').classList.toggle('is-playing',running&&!runPaused)};w.body.querySelector('[data-run-play]').onclick=()=>{running=true;runPaused=false;announceLog('MOCK 실행 시작 · 실제 엔진은 실행하지 않습니다.');refresh()};w.body.querySelector('[data-run-pause]').onclick=()=>{runPaused=true;refresh()};w.body.querySelector('[data-run-step]').onclick=()=>{running=true;runPaused=true;project.runFrame=(project.runFrame||0)+1;persist();refresh()};refresh();return w}
