function browserPendingChanges(w,baseline){
 const snapshots=baseline||{},all=new Set([...project.objects.map(o=>o.id),...Object.keys(snapshots)]);
 const lookup=id=>project.objects.find(o=>o.id===id)||snapshots[id];
 return [...all].filter(id=>{
  const current=project.objects.find(o=>o.id===id),before=snapshots[id];
  if(!browserObjectInScope(w,current,lookup)&&!browserObjectInScope(w,before,lookup))return false;
  return JSON.stringify(browserContentSnapshot(current))!==JSON.stringify(browserContentSnapshot(before));
 });
}
