let referenceTooltipCleanup=null;
function refreshHoveredReference(){const anchor=document.querySelector('.window[data-key^="browser"] [data-object]:hover');const object=anchor&&project.objects.find(item=>item.id===anchor.dataset.object);if(object)updateReference(object,anchor);else referenceTooltipCleanup?.()}
function updateReference(o,anchor){referenceTooltipCleanup?.();anchor??=document.querySelector('[data-object="'+CSS.escape(o.id)+'"]:hover');if(!anchor)return;const tip=document.createElement('div');tip.className='object-ref floating-object-ref';tip.setAttribute('role','tooltip');const refs=workspaceRuntime.state.shiftHeld?project.objects.filter(x=>x.inherits===o.id):project.objects.filter(x=>x.id===o.inherits);tip.innerHTML='<strong>'+ (workspaceRuntime.state.shiftHeld?'역참조 · Shift + Hover':'참조 · Hover')+'</strong><br>'+(refs.map(x=>esc(x.name)).join(' · ')||'연결된 상속 참조 없음')+'<br><small>분류: '+esc(project.objects.find(x=>x.id===o.parent)?.name||'Root')+' · ID: '+esc(o.id.slice(0,12))+'</small>';document.body.append(tip);const r=anchor.getBoundingClientRect(),t=tip.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(r.left,innerWidth-t.width-8))+'px';tip.style.top=Math.max(8,Math.min(r.top-t.height-8>=8?r.top-t.height-8:r.bottom+8,innerHeight-t.height-8))+'px';const events=new AbortController();const close=()=>{tip.remove();events.abort();if(referenceTooltipCleanup===close)referenceTooltipCleanup=null};referenceTooltipCleanup=close;anchor.addEventListener('mouseleave',close,{signal:events.signal});anchor.addEventListener('pointerdown',close,{signal:events.signal});document.addEventListener('scroll',close,{capture:true,signal:events.signal});window.addEventListener('resize',close,{signal:events.signal});}

function newObject(group='concept',parent=null){modal('새 '+groups[group]+' 만들기',`<form><div class="field"><label>이름</label><input id="object-name" required maxlength="60" placeholder="${group==='concept'?'새 개념':'Namespace.Name'}"></div>${group==='concept'?'<div class="field"><label>의미 객체 종류</label><select id="object-kind"><option>Concept</option><option>Category</option></select></div>':''}<p class="small">소유 팩 · ProjectPack</p><div class="actions"><button class="primary" type="submit">생성</button></div></form>`,(r,close)=>{$('form',r).onsubmit=e=>{e.preventDefault();const name=$('#object-name',r).value.trim();if(!name)return;const kind=group==='concept'?$('#object-kind',r).value:group==='feature'?'Feature':'Module';const o={id:uid(),name,kind,group,parent,icon:group==='concept'?'◇':group==='feature'?'✦':'▣',description:'',owner:'ProjectPack',...(kind==='Concept'?{hp:100,speed:2,damage:10,range:1,cooldown:2}:{})};project.objects.push(o);placeNamespaceObject(project,o);persist();refreshBrowserActions();close();workspaceRuntime.state.windows.forEach(browser=>{if(isBrowserWindowKey(browser.key))renderBrowserItems(browser)});updateNav();openEditor(o.id);announceLog(name+' 의미 객체 생성 · ProjectPack')}})}
function commitObjectName(o,name){
 name=name.trim();if(!name||name===o.name)return false;
 const oldName=o.name,oldParent=o.parent;o.name=name;
 const folders=placeNamespaceObject(project,o);
 const conflict=project.objects.some(other=>other!==o&&other.group===o.group&&(other.parent||null)===(o.parent||null)&&other.name.toLowerCase()===o.name.toLowerCase());
 if(conflict){project.objects=project.objects.filter(item=>!folders.includes(item));o.name=oldName;o.parent=oldParent;toast('같은 폴더에 같은 이름이 있어요.');return false}
 o.dirty=true;persist();syncObjectInputs(o.id);workspaceRuntime.state.windows.forEach(browser=>{if(isBrowserWindowKey(browser.key))renderBrowser(browser)});updateNav();return true;
}
function beginBrowserInlineRename(o,w){
 const button=$('[data-inline-name="'+CSS.escape(o.id)+'"]',w.body);if(!button)return renameObject(o);
 const input=document.createElement('input');input.className='browser-data-name-input';input.value=o.name;input.maxLength=60;input.setAttribute('aria-label',o.name+' 이름 변경');button.replaceWith(input);
 let done=false;const finish=save=>{if(done)return;done=true;if(save)commitObjectName(o,input.value);else renderBrowserItems(w)};
 input.onkeydown=e=>{e.stopPropagation();if(e.key==='Enter'){e.preventDefault();finish(true)}if(e.key==='Escape'){e.preventDefault();finish(false)}};input.onblur=()=>finish(true);input.focus();input.select();
}
function renameObject(o,w){
 if(w&&w.meta.density>=100&&$('[data-inline-name="'+CSS.escape(o.id)+'"]',w.body))return beginBrowserInlineRename(o,w);
 modal('이름 변경',`<form><div class="field"><label>새 이름</label><input value="${esc(o.name)}" required maxlength="60"></div><div class="actions"><button type="submit" class="primary">변경</button></div></form>`,(r,close)=>{$('form',r).onsubmit=e=>{e.preventDefault();if(commitObjectName(o,$('input',r).value))close()}});
}
function deleteObject(o){modal('의미 객체 삭제',`<p>${esc(o.name)}을 이 데모 작업 사본에서 삭제할까요?</p><p class="small">하위 객체는 Root로 이동합니다.</p><div class="actions"><button class="danger secondary" id="delete-object">삭제</button></div>`,(r,close)=>{$('#delete-object',r).onclick=()=>{project.objects=project.objects.filter(x=>x.id!==o.id);project.objects.filter(x=>x.parent===o.id).forEach(x=>x.parent=null);project.objects.filter(x=>x.inherits===o.id).forEach(x=>delete x.inherits);persist();close();closeWindow('object:'+o.id);refreshBrowserActions();workspaceRuntime.state.windows.forEach(browser=>{if(isBrowserWindowKey(browser.key))renderBrowserItems(browser)});updateNav()}})}
function contextMenu(x,y,items){$('.context-menu')?.remove();const m=document.createElement('div');m.className='context-menu';items.forEach(([name,fn])=>m.append(button(name,()=>{m.remove();fn()})));document.body.append(m);m.style.left=Math.max(8,Math.min(x,innerWidth-m.offsetWidth-8))+'px';m.style.top=Math.max(8,Math.min(y,innerHeight-m.offsetHeight-8))+'px';setTimeout(()=>{document.addEventListener('pointerdown',function dismiss(e){if(!m.contains(e.target)){m.remove();document.removeEventListener('pointerdown',dismiss)}}, {capture:true})},0)}
function objectContext(e,o,w){const functions=o.group==='concept'&&o.kind!=='Category'?[['Object.Preview','미리보기'],['Combat.Test','전투 테스트'],['Art.Generate','컨셉 아트 생성'],['Balance.Review','밸런스 검토']]:o.group==='feature'?[['Contract.Check','계약 검토']]:o.group==='module'?[['Module.Check','모듈 검토']]:[];contextMenu(e.clientX,e.clientY,[...(o.group==='concept'&&o.kind!=='Category'?[['바리에이션 생성',()=>beginBrowserCreate(w||workspaceRuntime.state.windows.get('browser'),'Concept',o)]]:[]),...functions.map(([id,name])=>[name,()=>functionForm(o,id,name)]),['상세 편집',()=>openEditor(o.id)],['스키마 열기',openSchema],['EY로 담기',()=>addYogiObject(o.id)],['Rename · F2',()=>renameObject(o,w)],['삭제 · Delete',()=>deleteObject(o)]])}
function functionForm(o,id,name){const art=id==='Art.Generate';const w=openWindow('function:'+o.id+':'+id,name+' · Function',450,art?460:330);w.body.innerHTML=`<div class="window-content"><span class="tag">Function · ${id==='ミ'?'Object.Preview':esc(id)}</span><h2 style="margin-top:15px">${name}</h2><form><div class="field"><label>Target · 자동 입력</label><input value="${esc(o.name)}" readonly></div>${art?'<div class="field" style="margin-top:15px"><label>Instruction</label><textarea rows="2" placeholder="표현하고 싶은 특징"></textarea></div><div class="fields" style="margin-top:15px"><div class="field"><label>Direction</label><select><option>정면</option><option>측면</option></select></div><div class="field"><label>Count</label><input type="number" min="1" max="4" value="1"></div></div>':'<p class="muted" style="font-size:14px;margin-top:18px">선택한 의미 객체에 대해 실행 요청 흐름을 시험합니다.</p>'}<div class="actions"><button class="primary" type="submit">실행 요청</button></div></form><div data-result></div></div>`;$('form',w.body).onsubmit=e=>{e.preventDefault();$('[data-result]',w.body).innerHTML='<div class="task">Mock 요청 접수 → 결과 확인<br><small>실제 Function이나 AI는 호출하지 않았습니다.</small></div>';announceLog(`${o.name} / ${name} 결과 확인`)};return w}
function openEditor(id,opts={}){const o=project.objects.find(o=>o.id===id);if(!o)return;selected=id;const key='object:'+id;if(workspaceRuntime.state.windows.has(key)){focusWindow(workspaceRuntime.state.windows.get(key));return workspaceRuntime.state.windows.get(key)}const w=openWindow(key,o.name+' · 데이터',405,475,{...opts,meta:{id}});w.body.innerHTML=`<div class="window-content"><div class="object-header"><span class="obj-icon">${o.icon}</span><div><h2>${esc(o.name)}</h2><span class="tag">${o.kind}</span> <span class="tag ${o.dirty?'amber':'green'}" data-dirty>${o.dirty?'저장되지 않은 변경':'작업 사본'}</span></div></div><div class="field"><label>이름</label><input data-obj="${id}" data-prop="name" value="${esc(o.name)}"></div><div class="field" style="margin-top:14px"><label>설명</label><textarea rows="2" data-obj="${id}" data-prop="description">${esc(o.description)}</textarea></div>${o.group==='concept'&&o.kind!=='Category'?`<div class="fields" style="margin-top:15px"><div class="field"><label>HP</label><input type="number" min="0" data-obj="${id}" data-prop="hp" value="${o.hp??0}"></div><div class="field"><label>이동속도</label><input type="number" min="0" step=".1" data-obj="${id}" data-prop="speed" value="${o.speed??0}"></div></div><div class="field" style="margin-top:15px"><label>공격 · 복합 값</label><button class="secondary" data-complex="${id}" style="text-align:left">${esc(o.attack||'설정하기')} · 상세 편집</button></div>`:''}<div class="editor-note">${o.helper?`${helpers.find(h=>h.id===o.helper)?.name}의 Worker가 작업 중<br>`:''}소유 · ProjectPack<br>분류 · ${esc(project.objects.find(x=>x.id===o.parent)?.name||'Root')}<br>${o.inherits?'상속 · '+esc(project.objects.find(x=>x.id===o.inherits)?.name)+'<br>':''}ID · ${esc(o.id)}<br>Save는 작업 사본 저장, Confirm은 검토 후 공유 상태 반영입니다.</div><div class="actions"><button class="secondary" data-schema>스키마</button><button class="secondary" data-save>Save</button><button class="primary" data-confirm>Confirm…</button></div></div>`;bindDataInputs(w.body);$('[data-schema]',w.body).onclick=openSchema;$('[data-save]',w.body).onclick=()=>saveObject(id);$('[data-confirm]',w.body).onclick=()=>openReview(id);saveLayouts();return w}
function saveObject(id){const o=project.objects.find(x=>x.id===id);project.saved[id]=structuredClone(o);o.dirty=false;persist();syncObjectInputs(id);announceLog(o.name+' / Save · 로컬 작업 사본 저장');toast('Save · 작업 사본을 저장했습니다. 공유 상태에는 아직 반영하지 않았어요.')}
function openComplex(id){const o=project.objects.find(x=>x.id===id);const w=openWindow('complex:'+id,'공격 · '+o.name,390,370);w.body.innerHTML=`<div class="window-content"><span class="tag">복합 데이터 · 공격</span><div class="field" style="margin-top:18px"><label>공격 이름</label><input data-obj="${id}" data-prop="attack" value="${esc(o.attack||'할퀴기')}"></div><div class="fields" style="margin-top:16px">${[['damage','피해량'],['range','범위'],['cooldown','쿨다운']].map(([prop,label])=>`<div class="field"><label>${label}</label><input type="number" min="0" step=".1" data-obj="${id}" data-prop="${prop}" value="${o[prop]??0}"></div>`).join('')}</div><div class="editor-note">뒤쪽 테이블과 동일한 객체 작업 사본을 편집합니다.</div><div class="actions"><button class="secondary" data-save>Save</button><button class="primary" data-confirm>Confirm…</button></div></div>`;bindDataInputs(w.body);$('[data-save]',w.body).onclick=()=>saveObject(id);$('[data-confirm]',w.body).onclick=()=>openReview(id);return w}
function openIssues(){const w=openWindow('issues','신문고',414,436);const render=()=>{w.body.innerHTML=`<div class="window-content"><div class="row spread"><h2>신문고</h2><span class="tag amber">${project.issues.filter(i=>!i.done).length} 미해결</span></div><p class="small">문제 · 요청 · 승인 · 충돌</p>${project.issues.map(i=>`<article class="issue"><div class="row"><span class="tag ${i.type==='충돌'?'amber':i.type==='오류'?'red':'green'}">${esc(i.type)}</span>${i.done?'<span class="tag">처리됨</span>':''}</div><h3>${esc(i.title)}</h3><p>${esc(i.description)}</p><div class="row"><button class="secondary" data-issue="${i.id}" ${i.done?'disabled':''}>${i.id==='approval'?'변경 검토':i.id==='conflict'?'충돌 협의':'Mock 재시도'}</button><button class="tag" data-attach="${i.id}">YogiBox 첨부</button></div>${i.yogi?'<p class="small">YogiBox 첨부됨 · <button class="tag" data-yogi="'+i.yogi+'">내용 보기</button></p>':''}</article>`).join('')||'<div class="empty">아직 요청이 없어요.</div>'}</div>`;$$('[data-issue]',w.body).forEach(b=>b.onclick=()=>{if(b.dataset.issue==='approval')openReview('slime',true);else if(b.dataset.issue==='conflict')openConflict();else{const issue=project.issues.find(i=>i.id===b.dataset.issue);issue.done=true;persist();refreshIssueCount();render();announceLog('미리보기 모의 재시도 완료')}});$$('[data-attach]',w.body).forEach(b=>b.onclick=()=>{const yogi=(project.yogis||[]).find(y=>y.sealed);if(!yogi){toast('먼저 YogiBox를 만들고 확정해 주세요.');openYogi();return}project.issues.find(i=>i.id===b.dataset.attach).yogi=yogi.id;persist();render()});$$('[data-yogi]',w.body).forEach(b=>b.onclick=()=>viewSentYogi(b.dataset.yogi))};w.refresh=render;render();return w}
function openConflict(){const o=project.objects.find(x=>x.id==='monster');if(!o){toast('Monster 객체가 없어 충돌 예시를 열 수 없습니다.');return}const w=openWindow('conflict','변경 충돌 · Monster',460,365);w.body.innerHTML=`<div class="window-content"><span class="tag amber">동일 의미 단위 · HP</span><h2 style="margin-top:15px">어떤 값을 작업 사본에 사용할까요?</h2><p class="muted" style="font-size:14px">토리와 사용자의 변경이 겹쳤습니다. 선택 후 Confirm 검토로 이어집니다.</p><div class="stack"><button class="secondary" data-value="${o.hp}">로컬 작업 사본 · ${o.hp}</button><button class="secondary" data-value="140">토리 제안 · 140</button></div></div>`;$$('[data-value]',w.body).forEach(b=>b.onclick=()=>{o.hp=Number(b.dataset.value);o.dirty=true;syncObjectInputs(o.id);project.issues.find(i=>i.id==='conflict').done=true;persist();refreshIssueCount();workspaceRuntime.state.windows.get('issues')?.refresh?.();closeWindow('conflict');openReview(o.id)})}
function openReview(id,ai=false){let o=project.objects.find(x=>x.id===id);if(!o)o=project.objects.find(x=>x.dirty)||project.objects.find(x=>x.id==='slime')||project.objects.find(x=>x.kind!=='Category');if(!o){toast('검토할 의미 객체를 먼저 만들어 주세요.');return}const baseline=project.confirmed[o.id]||{hp:o.id==='monster'?120:o.hp,speed:o.id==='slime'?1.8:o.speed,name:o.name,description:o.description,attack:o.attack};const proposal=ai?{...o,speed:2.1}:structuredClone(o);const fields=['name','description','hp','speed','attack','damage','range','cooldown'].filter(k=>proposal[k]!==undefined&&(ai?k==='speed':proposal[k]!==baseline[k]));if(!fields.length)fields.push('hp' in o?'hp':'name');const w=openWindow('review:'+o.id,'변경 검토 · '+o.name,495,390);w.body.innerHTML=`<div class="window-content"><span class="tag ${ai?'green':'amber'}">${ai?'루미 제안':'로컬 작업 사본'} · 공유 상태 반영 전</span><h2 style="margin-top:15px">${esc(o.name)}</h2><p class="small">적용할 변경을 선택하세요. Confirm만 공유 상태를 바꿉니다.</p>${fields.map(k=>`<label class="change-row"><input type="checkbox" data-change="${k}" checked><strong>${k}</strong><del>${esc(baseline[k]??'없음')}</del><span>→</span><ins>${esc(proposal[k])}</ins></label>`).join('')}<div class="actions"><button class="secondary" data-reject>거절</button><button class="primary" data-apply>선택 변경 Confirm</button></div></div>`;$('[data-reject]',w.body).onclick=()=>{closeWindow(w.key);announceLog(o.name+' 변경 검토 보류')};$('[data-apply]',w.body).onclick=()=>{const selectedFields=$$('[data-change]:checked',w.body).map(b=>b.dataset.change);if(!selectedFields.length){toast('적용할 변경을 선택하세요.');return}project.confirmed[o.id]??={...baseline};selectedFields.forEach(k=>{project.confirmed[o.id][k]=proposal[k];if(ai)o[k]=proposal[k]});o.dirty=true;if(ai){const issue=project.issues.find(i=>i.id==='approval');if(issue)issue.done=true}persist();syncObjectInputs(o.id);refreshIssueCount();workspaceRuntime.state.windows.get('issues')?.refresh?.();announceLog(`${o.name} / Confirm · ${selectedFields.join(', ')} 공유 상태 반영`);toast('선택한 변경을 가상 공유 상태에 반영했습니다.');closeWindow(w.key)};return w}
function openSchema(){const w=openWindow('schema','스키마 · Monster',660,390);const render=()=>{w.body.innerHTML=`<div class="window-content"><div class="row spread"><div><h2>Monster Schema</h2><small>객체 데이터와 View 정의는 별도로 유지</small></div><button class="secondary" data-add>＋ 필드</button></div><div style="overflow:auto;margin-top:20px"><div class="schema-row small"><span>필드 이름</span><span>타입</span><span>값 개수</span><span>구조</span><span></span></div>${project.schemas.map((f,i)=>`<div class="schema-row" data-index="${i}"><input value="${esc(f.name)}" data-field="name" aria-label="필드 이름"><select data-field="type" aria-label="필드 타입">${['문자열','숫자','참조','불리언'].map(t=>`<option ${t===f.type?'selected':''}>${t}</option>`).join('')}</select><select data-field="count" aria-label="값 개수">${['단일','다중'].map(t=>`<option ${t===f.count?'selected':''}>${t}</option>`).join('')}</select><select data-field="kind" aria-label="필드 구조">${['일반','복합','기능'].map(t=>`<option ${t===f.kind?'selected':''}>${t}</option>`).join('')}</select><button data-remove="${i}" aria-label="필드 삭제">×</button></div>`).join('')}</div><div class="editor-note">스키마 편집은 목업입니다. 브라우저 Data 열은 현재 보이는 객체가 실제로 가진 필드로 구성됩니다.</div><div class="actions"><button class="primary" data-save>작업 사본 저장</button></div></div>`;$$('[data-field]',w.body).forEach(input=>input.onchange=()=>{const i=Number(input.closest('[data-index]').dataset.index);project.schemas[i][input.dataset.field]=input.value;persist()});$$('[data-remove]',w.body).forEach(b=>b.onclick=()=>{project.schemas.splice(Number(b.dataset.remove),1);persist();render()});$('[data-add]',w.body).onclick=()=>{project.schemas.push({name:'newField',type:'문자열',count:'단일',kind:'일반'});persist();render()};$('[data-save]',w.body).onclick=()=>{persist();toast('스키마 작업 사본 저장')}};render();return w}
function openMap(){const w=openWindow('map','개념 맵 · 관계 View',650,475);const render=(focusId)=>{const nodes=['world','unit','monster','slime','item','weapon'].map(id=>project.objects.find(o=>o.id===id)).filter(Boolean);const positions={world:[210,15],unit:[60,125],monster:[215,130],slime:[215,255],item:[435,125],weapon:[435,255]};w.body.innerHTML=`<div class="window-content"><div class="row spread"><div><h2>개념 사이의 관계</h2><small>${focusId?'집중 탐색 · '+esc(project.objects.find(o=>o.id===focusId)?.name):'노드 선택으로 관계 강조 · 더블클릭으로 집중'}</small></div><button class="tag" data-reset>전체 보기</button></div><div style="overflow:auto"><div class="map"><svg viewBox="0 0 570 360"><defs><marker id="map-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10" fill="#76e4c2"/></marker></defs>${[['unit','monster'],['monster','slime'],['item','weapon'],['world','unit'],['world','item']].map(([a,b])=>{const [x1,y1]=positions[a],[x2,y2]=positions[b];return `<path data-edge="${a} ${b}" d="M${x1+50} ${y1+55} L${x2+50} ${y2}" fill="none" stroke="${a==='world'?'#526570':'#76e4c2'}" stroke-width="1.5" ${a==='world'?'stroke-dasharray="5 5"':''} marker-end="url(#map-arrow)" opacity="${!focusId||[a,b].includes(focusId)?1:.15}"/>`}).join('')}</svg>${nodes.map(o=>`<button class="map-node ${o.inherits?'variation':''} ${o.id===focusId?'selected':''}" style="left:${positions[o.id][0]}px;top:${positions[o.id][1]}px" data-node="${o.id}">${esc(o.name)}</button>`).join('')}</div></div><div class="map-legend"><span>━━ 상속 / Variation</span><span>┄┄ 분류 · Category</span></div></div>`;$$('[data-node]',w.body).forEach(b=>{b.onclick=()=>render(b.dataset.node);b.ondblclick=()=>{render(b.dataset.node);openEditor(b.dataset.node)}});$('[data-reset]',w.body).onclick=()=>render()};render();return w}
function openCustom(){const w=openWindow('custom','즉석 테이블 · Custom View',650,385);const render=(query='몬스터 능력치 비교')=>{const items=project.objects.filter(o=>o.group==='concept'&&o.kind!=='Category'&&(query.includes('무기')?o.id==='weapon':true));w.body.innerHTML=`<div class="window-content"><div class="row spread"><div><h2>즉석 테이블</h2><small>원본 의미 객체를 다른 방식으로 보기</small></div><span class="tag">MOCK VIEW</span></div><form class="form-line" style="margin:18px 0"><input aria-label="View 요청" value="${esc(query)}"><button class="secondary" type="submit">구성</button></form><div style="overflow:auto">${objectTable(items)}</div><div class="editor-note">같은 작업 사본을 공유합니다. 맞춤 View 없이도 브라우저의 Data 모드로 접근할 수 있어요.</div></div>`;bindDataInputs(w.body);$('form',w.body).onsubmit=e=>{e.preventDefault();render($('form input',w.body).value)}};render();return w}
