function openAugment(){const space=$('#workspace');if(!space)return;const existing=space.querySelector('.augment-overlay');if(existing){existing.querySelector('button')?.focus();return}const owner=project,previous=document.activeElement;owner.augmentOffer??={round:0,offset:owner.augmentNextOffset||0,reason:'몬스터와 아이템을 함께 만드는 프로젝트를 확장할 수 있어요'};const offer=owner.augmentOffer;const el=document.createElement('section');el.className='augment-overlay';el.setAttribute('role','dialog');el.setAttribute('aria-label','증강 선택');const close=()=>{el.remove();document.querySelectorAll('.helper-sd-companion.is-augment-raised').forEach(card=>card.classList.remove('is-augment-raised'));previous?.focus()};document.querySelectorAll('.helper-sd-companion.is-augment-raised').forEach(card=>card.classList.remove('is-augment-raised'));const render=()=>{const choices=Array.from({length:3},(_,i)=>augmentOptions[((offer.offset||0)+offer.round*3+i)%augmentOptions.length]);el.innerHTML='<div class="augment-panel"><header class="augment-heading"><h2>'+esc(offer.reason)+'</h2></header><div class="augment-grid">'+(augmentRemaining()?choices.map((a,i)=>'<article class="augment-card" data-grade="'+a.grade+'" style="--card-order:'+i+'"><small class="augment-grade" title="'+augmentGrades[a.grade].impact+'">'+a.grade+'</small><h3>'+esc(a.name)+'</h3><p>'+esc(a.desc)+'</p><div class="tags">'+a.tags.map(t=>'<span class="tag">'+esc(t)+'</span>').join('')+'</div><small>'+a.work+'</small><button class="primary" data-select-augment="'+i+'">이 방향 선택</button></article>').join(''):'<p class="augment-empty">남은 증강이 없어요.</p>')+'</div><footer class="augment-footer"><button class="secondary augment-reroll" data-reroll '+(!augmentRemaining()?'disabled':'')+'>↻ 리롤</button><div class="augment-footer-actions"><button data-cancel title="현재 제안을 파기하고 다음에는 다른 제안 보기">취소</button><button data-defer title="현재 제안을 유지하고 나중에 다시 보기">보류하기</button><button data-propose>제안하기</button></div></footer></div>';el.querySelectorAll('[data-select-augment]').forEach(b=>b.onclick=()=>{if(!augmentRemaining())return;const a=choices[Number(b.dataset.selectAugment)];owner.tasks.push({id:uid(),name:a.name,status:'Task 대기',grade:a.grade});owner.augmentRemaining=augmentRemaining()-1;delete owner.augmentOffer;persist();refreshAugmentCount();announceLog('증강 선택 → Task 대기 / '+a.name);close()});el.querySelector('[data-reroll]').onclick=()=>{offer.round++;persist();render();el.querySelector('[data-reroll]').focus()};el.querySelector('[data-cancel]').onclick=()=>{owner.augmentNextOffset=((offer.offset||0)+(offer.round+1)*3)%augmentOptions.length;delete owner.augmentOffer;persist();close()};el.querySelector('[data-defer]').onclick=()=>{persist();close()};el.querySelector('[data-propose]').onclick=()=>modal('증강 제안하기','<form class="stack"><label for="augment-proposal">어떤 변화를 제안하고 싶나요?</label><textarea id="augment-proposal" rows="4" required></textarea><button class="primary" type="submit">제안하기</button></form>',(root,dismiss)=>{root.querySelector('form').onsubmit=e=>{e.preventDefault();const text=root.querySelector('textarea').value.trim();if(!text)return;owner.augmentProposals??=[];owner.augmentProposals.push({id:uid(),text,status:'검토 대기'});persist();dismiss();toast('증강 제안을 남겼어요.')}})};space.append(el);render();persist();el.onkeydown=e=>{if(e.key==='Escape'){e.stopPropagation();persist();close()}};el.querySelector('[data-reroll]').focus()}
