function startYogiCapture(){const compact=document.querySelector('.yogi-clipboard.is-package');if(compact&&project){const draft=project.yogis?.find(y=>y.id===compact.dataset.yogiId);if(draft){draft.sealed=false;persist();openYogi(draft.id)}}if(yogiCapture){yogiCapture();return}if(!project)return;const owner=project;let pack=owner.yogis?.find(y=>!y.sealed)||null,down=null,target=null;const elementIds=new WeakMap();const cursor=document.createElement('div'),outline=document.createElement('div');cursor.className='yogi-cursor';cursor.textContent='📦';outline.className='yogi-selection';document.body.append(cursor,outline);document.body.classList.add('yogi-capturing');const eligible=el=>el instanceof Element&&!el.closest('.yogi-clipboard,.yogi-context-menu,#yogi-bubble,.yogi-cursor,.yogi-selection');const rectOf=(x,y)=>({left:Math.min(down.x,x),top:Math.min(down.y,y),width:Math.abs(x-down.x),height:Math.abs(y-down.y)});const draw=r=>Object.assign(outline.style,{display:'block',left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px'});const move=e=>{cursor.style.left=e.clientX+14+'px';cursor.style.top=e.clientY+14+'px';if(down){draw(rectOf(e.clientX,e.clientY));return}target=eligible(e.target)?(e.target.closest('button,a,input,select,textarea,[role="button"],[data-object],[data-obj],[data-node],.message')||e.target):null;if(target)draw(target.getBoundingClientRect());else outline.style.display='none'};const press=e=>{if(e.button!==0||!eligible(e.target))return;e.preventDefault();e.stopImmediatePropagation();target=e.target.closest('button,a,input,select,textarea,[role="button"],[data-object],[data-obj],[data-node],.message')||e.target;down={x:e.clientX,y:e.clientY,target}};const release=async e=>{if(!down)return;e.preventDefault();e.stopImmediatePropagation();if(!pack){pack={id:uid(),ey:[],lay:[],note:'',sealed:false};owner.yogis??=[];owner.yogis.push(pack)}const area=rectOf(e.clientX,e.clientY),selectedTarget=down.target;down=null;outline.style.display='none';if(Math.hypot(area.width,area.height)>5){try{const image=await captureYogiRegion(area);if(!owner.yogis.includes(pack))return;pack.lay.push({label:'선택 영역',bounds:area,image,capturedAt:new Date().toISOString()})}catch{toast('선택 영역을 이미지로 담지 못했어요. 다시 선택해 주세요.');return}}else{const el=selectedTarget,id=el.dataset.object||el.dataset.obj||el.dataset.node||el.id||elementIds.get(el)||'element:'+uid();elementIds.set(el,id);if(!pack.ey.includes(id))pack.ey.push(id);pack.targets??={};pack.targets[id]=yogiTargetReference(el);yogiLiveTargets.set(id,el)}down=null;outline.style.display='none';persist();openYogi(pack.id)};const click=e=>{if(eligible(e.target)){e.preventDefault();e.stopImmediatePropagation()}};const key=e=>{if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();cleanup()}};const context=e=>{e.preventDefault();e.stopImmediatePropagation();cleanup()};const cleanup=()=>{document.removeEventListener('contextmenu',context,true);document.removeEventListener('pointermove',move,true);document.removeEventListener('pointerdown',press,true);document.removeEventListener('pointerup',release,true);document.removeEventListener('click',click,true);document.removeEventListener('keydown',key,true);cursor.remove();outline.remove();document.body.classList.remove('yogi-capturing');yogiCapture=null;syncYogiState()};yogiCapture=cleanup;document.addEventListener('contextmenu',context,true);document.addEventListener('pointermove',move,true);document.addEventListener('pointerdown',press,true);document.addEventListener('pointerup',release,true);document.addEventListener('click',click,true);document.addEventListener('keydown',key,true)}
