function showYogiContents(btn,y,owner,box){const was=btn.getAttribute('aria-expanded')==='true';closeYogiContents?.();if(was)return;const key=btn.dataset.type,m=document.createElement('div'),events=new AbortController();m.className='context-menu yogi-context-menu';m.setAttribute('role','menu');m.setAttribute('aria-label',key==='ey'?'Exactly Yogi':'Look at Yogi');btn.setAttribute('aria-expanded','true');document.body.append(m);const close=()=>{m.remove();btn.setAttribute('aria-expanded','false');events.abort();closeYogiContents=null};closeYogiContents=close;const draw=()=>{m.innerHTML='<div class="yogi-menu-scroll">'+(y[key].map((item,i)=>{const label=key==='ey'?(y.targets?.[item]?.label||owner.objects?.find(o=>o.id===item)?.name||item):(item.label||'선택 영역')+' '+(i+1);return '<div class="yogi-content-row">'+(key==='ey'?'<button class="yogi-reference" data-run-reference="'+esc(item)+'">'+esc(label)+'</button>':(item.image?'<img class="yogi-menu-image" src="'+esc(item.image)+'" alt="'+esc(label)+'">':'<span>'+esc(label)+'</span>'))+'<button role="menuitem" data-remove="'+i+'" aria-label="제거">×</button></div>'}).join('')||'<p class="small">담긴 내용이 없어요.</p>')+'</div>';$$('[data-run-reference]',m).forEach(b=>b.onclick=e=>{e.stopPropagation();close();executeYogiTarget(y,b.dataset.runReference)});$$('[data-remove]',m).forEach(b=>b.onclick=()=>{y[key].splice(Number(b.dataset.remove),1);if(!y.ey.length&&!y.lay.length){owner.yogis=owner.yogis.filter(item=>item.id!==y.id);close();if(yogiCapture)yogiCapture();box.remove();persist();syncYogiState();return}persist();$('b',btn).textContent=y[key].length;$('[data-confirm]',box).disabled=!y.ey.length&&!y.lay.length;draw();($('button',m)||btn).focus()});const r=btn.getBoundingClientRect();m.style.left=Math.max(8,Math.min(r.left+r.width/2-m.offsetWidth/2,innerWidth-m.offsetWidth-8))+'px';const above=r.top-m.offsetHeight-10>=8;m.classList.toggle('opens-below',!above);m.style.top=Math.max(8,Math.min(innerHeight-m.offsetHeight-8,above?r.top-m.offsetHeight-10:r.bottom+10))+'px';m.style.setProperty('--yogi-pivot',Math.max(12,Math.min(m.offsetWidth-12,r.left+r.width/2-parseFloat(m.style.left)))+'px')};draw();document.addEventListener('pointerdown',e=>{if(!m.contains(e.target)&&!btn.contains(e.target))close()},{capture:true,signal:events.signal});document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close();btn.focus()}},{signal:events.signal});window.addEventListener('resize',close,{signal:events.signal})}
