function syncYogiState(){const active=!!document.querySelector('.yogi-clipboard:not(.is-package)')||!!yogiCapture;const bubble=$('#yogi-bubble');if(bubble){bubble.innerHTML=active?yogiOpenIcon():'📦';bubble.classList.toggle('is-yogi-open',active);bubble.setAttribute('aria-pressed',String(active))}const cursor=$('.yogi-cursor');if(cursor)cursor.innerHTML=yogiOpenIcon()}
function openYogi(id){if(typeof id==='string'&&(db.sentYogis?.[id]||db.projects.some(p=>p.messages?.some(m=>m.yogi===id))||Object.values(db.globalChats).some(messages=>messages.some(m=>m.yogi===id)))){viewSentYogi(id);return}if(typeof id!=='string'){startYogiCapture();syncYogiState();return}const owner=project,y=owner?.yogis?.find(x=>x.id===id);if(!y)return;let el=document.querySelector('.yogi-clipboard:not(.yogi-readonly)');if(!el){el=document.createElement('section');el.className='yogi-clipboard';el.setAttribute('role','dialog');el.setAttribute('aria-label','YogiBox');document.body.append(el)}el.dataset.yogiId=y.id;el.classList.remove('is-package');const render=()=>{closeYogiContents?.();el.innerHTML='<header class="yogi-clipboard-head"><strong><span class="yogi-title-icon">'+yogiOpenIcon()+'</span> YogiBox</strong></header><div class="yogi-clipboard-body"><div class="yogi-types">'+[['ey','👆','Exactly Yogi'],['lay','🖼️','Look at Yogi']].map(([key,icon,label])=>'<button class="yogi-type" data-type="'+key+'" aria-expanded="false"><span class="yogi-type-circle">'+icon+'<b>'+y[key].length+'</b></span><span>'+label+'</span></button>').join('')+'</div><div class="yogi-content-list" hidden></div><div class="field"><label for="yogi-note">설명</label><textarea id="yogi-note" rows="3" placeholder="함께 볼 맥락을 적어주세요…">'+esc(y.note)+'</textarea></div><div class="yogi-clipboard-actions"><button class="secondary" data-delete>삭제</button><button class="primary" data-confirm '+(!y.ey.length&&!y.lay.length?'disabled':'')+'>확정</button></div></div>';$('textarea',el).oninput=e=>{y.note=e.target.value;persist()};$$('[data-type]',el).forEach(btn=>btn.onclick=()=>showYogiContents(btn,y,owner,el));$('[data-confirm]',el).onclick=()=>{closeYogiContents?.();y.sealed=true;if(yogiCapture)yogiCapture();persist();el.classList.add('is-package');el.setAttribute('aria-label','전달할 YogiBox');el.innerHTML='<div class="yogi-package" draggable="true" tabindex="0" aria-label="도우미에게 드래그하여 전달"><span>📦</span><small>YogiBox</small><div class="yogi-package-counts"><span title="Exactly Yogi">👆 '+y.ey.length+'</span><span title="Look at Yogi">🖼️ '+y.lay.length+'</span></div></div>';const box=$('.yogi-package',el);let dragged=false;const reopen=()=>{if(dragged)return;y.sealed=false;persist();openYogi(y.id)};box.onclick=reopen;box.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();reopen()}};let dragOffset={x:0,y:0};box.ondragend=e=>{if(el.isConnected&&e.dataTransfer?.dropEffect==='none'&&(e.clientX||e.clientY)){el.style.transform='none';el.style.bottom='auto';el.style.left=Math.max(8,Math.min(innerWidth-el.offsetWidth-8,e.clientX-dragOffset.x))+'px';el.style.top=Math.max(8,Math.min(innerHeight-el.offsetHeight-8,e.clientY-dragOffset.y))+'px'}setTimeout(()=>{dragged=false},0)};box.ondragstart=e=>{const bounds=el.getBoundingClientRect();dragOffset={x:e.clientX-bounds.left,y:e.clientY-bounds.top};dragged=true;e.dataTransfer.setData('application/x-yogibox',y.id);e.dataTransfer.effectAllowed='move'};syncYogiState()};$('[data-delete]',el).onclick=()=>{closeYogiContents?.();owner.yogis=owner.yogis.filter(x=>x.id!==y.id);persist();if(yogiCapture)yogiCapture();el.remove();syncYogiState()};const head=$('.yogi-clipboard-head',el);head.append($('.yogi-types',el));$$('[data-type]',head).forEach(b=>{b.title=b.dataset.type==='ey'?'Exactly Yogi':'Look at Yogi';b.setAttribute('aria-label',b.title)});head.onpointerdown=e=>{if(e.button!==0||e.target.closest('button'))return;const r=el.getBoundingClientRect(),sx=e.clientX,sy=e.clientY;head.setPointerCapture(e.pointerId);head.onpointermove=m=>{el.style.transform='none';el.style.bottom='auto';el.style.left=Math.max(0,Math.min(innerWidth-el.offsetWidth,r.left+m.clientX-sx))+'px';el.style.top=Math.max(0,Math.min(innerHeight-el.offsetHeight,r.top+m.clientY-sy))+'px'};head.onpointerup=()=>{head.onpointermove=null;head.onpointerup=null}};syncYogiState()};render();return {el,body:el,refresh:render}}
function yogiDropHelper(el){const chat=el.closest('[data-yogi-helper]');if(chat)return chat.dataset.yogiHelper;const tile=el.closest('.home-side [data-helper]');if(tile)return tile.dataset.helper;const card=el.closest('.helper-profile-card,.helper-sd-companion');return card?._sourceButton?.dataset.helper||card?._sourceButton?.dataset.ownedHelper||card?.querySelector('[data-role-helper]')?.dataset.roleHelper}
