function addYogiObject(id){project.yogis??=[];let y=project.yogis.find(y=>!y.sealed);if(!y){y={id:uid(),ey:[],lay:[],note:'',sealed:false};project.yogis.push(y)}if(!y.ey.includes(id))y.ey.push(id);persist();openYogi(y.id);toast('의미 객체의 ID를 EY로 담았습니다.')}
function deliverYogi(id,target){const y=project.yogis?.find(x=>x.id===id);if(!y)return;if(target==='chat'){const key='project:'+project.id;yogiAttachments[key]??=[];if(!yogiAttachments[key].includes(id))yogiAttachments[key].push(id);refreshChat();renderProjectYogiAttachments();document.querySelector('.yogi-clipboard.is-package')?.remove()}else if(target==='player'){project.messages.push({who:'나',text:'Player에게 YogiBox를 전달했습니다.',yogi:id});refreshChat()}else{yogiAttachments[target]??=[];if(!yogiAttachments[target].includes(id))yogiAttachments[target].push(id);closeWindow('helper-'+target);const chats=[...document.querySelectorAll('[data-yogi-helper]')].filter(el=>el.dataset.yogiHelper===target);if(chats.length){chats.forEach(el=>{const input=el.querySelector('textarea'),draft=input?.value||'';el._refreshYogiChat?.();if(el.querySelector('textarea'))el.querySelector('textarea').value=draft});const card=chats[0].closest('.participant-expanded-card');if(card)raiseParticipantWindow(card)}else{const tile=[...document.querySelectorAll('.home-side [data-helper]')].find(el=>el.dataset.helper===target);if(tile)tile.click()}}persist();toast('YogiBox를 첨부했어요. 보내기 전까지 취소할 수 있어요.')}
