function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'read_confectory_workspace',title:'작업 공간 읽기',description:'Read the current prototype project and semantic objects without changing state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(){return {page,project:project?{id:project.id,name:project.name,objects:project.objects.map(o=>({id:o.id,name:o.name,kind:o.kind})),windows:[...workspaceRuntime.state.windows.keys()]}:null}}},{name:'open_semantic_object_editor',title:'의미 객체 편집창 열기',description:'Open an existing semantic object in the current project. Does not modify data or confirm changes.',inputSchema:{type:'object',properties:{objectId:{type:'string'}},required:['objectId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.objectId!=='string'||Object.keys(input).some(k=>k!=='objectId'))throw new Error('objectId 문자열만 입력하세요.');if(page!=='work'||!project?.objects.some(o=>o.id===input.objectId))throw new Error('현재 프로젝트에서 객체를 찾을 수 없습니다.');openEditor(input.objectId);return {opened:true,objectId:input.objectId}}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
