function coworkerTiles(){const people=[['김민서','기획자'],['이준호','개발자'],['박서연','디자이너'],['정도윤','아티스트'],['한지우','사운드']];return people.map(([name,role],i)=>db.blockedCoworkers?.[i]?'':`<button type="button" data-coworker="${i}" class="coworker-profile" aria-label="${name}, ${role}, ${i<2?'온라인':'오프라인'}${i===0&&!db.coworkerRead?', 안 읽은 대화 3개':''}"><span class="avatar agent-avatar coworker-avatar"><svg viewBox="0 0 32 32" aria-hidden="true"><circle cx="16" cy="10" r="6" fill="currentColor"/><path d="M5 29v-3a11 11 0 0 1 22 0v3Z" fill="currentColor"/></svg><span class="connection-dot ${i<2?'':'offline'}" aria-hidden="true"></span>${i===0&&!db.coworkerRead?'<span class="coworker-unread" aria-label="안 읽은 대화 3개">3</span>':''}</span><span class="meta"><strong>${name}</strong><small>${role}</small></span></button>`).join('')}

function participantSectionStart(key,label){return `<section class="participant-section"><button class="participant-section-toggle" data-participant-toggle="${key}" aria-label="${esc(label)}" title="${esc(label)}" aria-expanded="true" aria-controls="participant-${key}"><span class="participant-heading-label">${participantHeadingIcon(key)}<span class="participant-category-name">${label.split("(")[0].trim()}</span><span class="participant-category-count">${label.slice(label.indexOf("("))}</span>${participantHasNews(key)?'<span class="news-orb" role="img" aria-label="새 소식"></span>':''}</span><svg class="section-chevron" viewBox="0 0 16 16" aria-hidden="true"><path d="m4 6 4 4 4-4" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></button>`}
function participantSection(key,label,content){return participantSectionStart(key,label)+`<div class="participant-grid" id="participant-${key}">${content}</div></section>`}

function coworkerChat(i){const people=[['김민서','기획자','오늘은 세계관과 퀘스트 흐름을 정리하고 있어요.'],['이준호','개발자','새로운 기능을 함께 만들어요.'],['박서연','디자이너','화면에 작은 즐거움을 담아요.'],['정도윤','아티스트','새로운 캐릭터를 구상하고 있어요.'],['한지우','사운드','이야기에 어울리는 소리를 찾고 있어요.']];const [name,role,status]=people[i];db.coworkerChats??={};db.coworkerChats[i]??=i===0?[{who:name,text:'새 프로젝트의 기획 초안을 정리했어요.'},{who:name,text:'몬스터와 아이템 구성부터 함께 살펴볼까요?'},{who:name,text:'준비되면 편하게 이야기해 주세요.'}]:[];if(i===0){db.coworkerRead=true;document.querySelector('[data-coworker="0"] .coworker-unread')?.remove();document.querySelector('[data-coworker="0"]').setAttribute('aria-label',name+', '+role+', 온라인')}if(i===0&&!db.coworkerChatExampleAdded){db.coworkerChats[i].push({who:'나',text:'좋아요. 몬스터 구성부터 함께 확인해 볼게요.',time:'14:33'});db.coworkerChatExampleAdded=true}db.coworkerChats[i].forEach((m,j)=>{m.time??='14:'+String(30+j).padStart(2,'0')});persist();modal(name+' · 대화',`<div class="coworker-chat-profile"><span class="avatar agent-avatar coworker-avatar"><svg viewBox="0 0 32 32" aria-hidden="true"><circle cx="16" cy="10" r="6" fill="currentColor"/><path d="M5 29v-3a11 11 0 0 1 22 0v3Z" fill="currentColor"/></svg><span class="connection-dot ${i<2?'':'offline'}"></span></span><div><div class="coworker-profile-name"><h3>${name}</h3><p class="small">${role} · ${i<2?'온라인':'오프라인'}</p></div><p class="coworker-status">${status}</p></div></div><section class="coworker-chat"><div class="coworker-messages" aria-live="polite"></div><form class="coworker-compose"><input aria-label="메시지" placeholder="메시지를 입력하세요" maxlength="2000" autocomplete="off"><button class="primary" type="submit">보내기</button></form></section>`,(r,close)=>{r.classList.add('coworker-chat-modal');const closeButton=r.querySelector('[data-close]');r.querySelector('.coworker-chat-profile').append(closeButton);r.querySelector('.modal-head').remove();const controls=document.createElement('div');controls.className='coworker-card-actions';controls.innerHTML=`<button type="button" class="coworker-notify" aria-label="알림 ${db.coworkerMuted?.[i]?'켜기':'끄기'}" title="알림 ${db.coworkerMuted?.[i]?'켜기':'끄기'}" aria-pressed="${!db.coworkerMuted?.[i]}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4"/></svg></button><button type="button" class="coworker-block" aria-label="${esc(name)} 차단" title="차단"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m5.6 5.6 12.8 12.8"/></svg></button>`;r.append(controls);r.querySelector('.coworker-notify').onclick=e=>{db.coworkerMuted??={};db.coworkerMuted[i]=!db.coworkerMuted[i];e.currentTarget.setAttribute('aria-label','알림 '+(db.coworkerMuted[i]?'켜기':'끄기'));e.currentTarget.title='알림 '+(db.coworkerMuted[i]?'켜기':'끄기');e.currentTarget.setAttribute('aria-pressed',String(!db.coworkerMuted[i]));if(db.coworkerMuted[i])document.querySelector('[data-coworker="'+i+'"] .participant-news-badge')?.remove();persist()};r.querySelector('.coworker-block').onclick=()=>{close();modal('친구 차단',`<p>${esc(name)}님을 차단하시겠습니까?</p><p class="small">차단하면 친구 목록에서 숨겨지고 더 이상 알림을 받지 않습니다. 친구 추가 화면에서 차단을 해제할 수 있습니다.</p><div class="actions"><button type="button" id="cancel-block">취소</button><button type="button" class="primary" id="confirm-block">차단</button></div>`,(warning,done)=>{$('#cancel-block',warning).onclick=done;$('#confirm-block',warning).onclick=()=>{db.blockedCoworkers??={};db.blockedCoworkers[i]=true;persist();document.querySelector('[data-coworker="'+i+'"]')?.remove();updateCoworkerCount();done()}})};const list=r.querySelector('.coworker-messages');const render=()=>{list.innerHTML=db.coworkerChats[i].map((m,j)=>`<div class="coworker-message ${m.who==='나'?'self':''} ${j>0&&db.coworkerChats[i][j-1].who===m.who?'consecutive':''}">${m.who!=='나'&&(j===0||db.coworkerChats[i][j-1].who!==m.who)?'<small>'+esc(m.who)+'</small>':''}<div class="coworker-message-row"><p>${esc(m.text)}</p><time>${esc(m.time)}</time></div></div>`).join('')||'<p class="small">대화를 시작해 보세요.</p>';list.scrollTop=list.scrollHeight};render();r.querySelector('form').onsubmit=e=>{e.preventDefault();const input=r.querySelector('input');const text=input.value.trim();if(!text)return;db.coworkerChats[i].push({who:'나',text,time:new Date().toLocaleTimeString('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false})});persist();input.value='';render();input.focus()}})}

function coworkerHover(b){if(document.querySelector('.participant-expanded-card:not(.is-pinned)'))return;document.querySelector('.coworker-hover-card')?.remove();const i=Number(b.dataset.coworker);const people=[['김민서','기획자','오늘은 세계관과 퀘스트 흐름을 정리하고 있어요.'],['이준호','개발자','새로운 기능을 함께 만들어요.'],['박서연','디자이너','화면에 작은 즐거움을 담아요.'],['정도윤','아티스트','새로운 캐릭터를 구상하고 있어요.'],['한지우','사운드','이야기에 어울리는 소리를 찾고 있어요.']];const [name,role,status]=people[i];const card=document.createElement('aside');card.className='coworker-hover-card';card.setAttribute('role','tooltip');card.innerHTML=`<div class="coworker-hover-head">${b.querySelector('.coworker-avatar').outerHTML}<div><strong>${name}</strong><small>${role} · ${i<2?'온라인':'오프라인'}</small></div></div><p>${status}</p>`;document.body.append(card);const rect=b.getBoundingClientRect();const side=document.querySelector('.home-side').getBoundingClientRect();const size=card.getBoundingClientRect();card.style.left=Math.max(8,Math.min(side.right+12,innerWidth-size.width-8))+'px';card.style.top=Math.max(8,Math.min(rect.top,innerHeight-size.height-8))+'px'}

function participantHover(b){if(document.querySelector('.participant-expanded-card:not(.is-pinned)'))return;document.querySelector('.coworker-hover-card')?.remove();let name,description,status;if(b.dataset.helper){const h=helpers.find(h=>h.id===b.dataset.helper);if(!h)return;name=h.name;description=h.description;status=h.status}else{const a=db.extraAgents.find(a=>a.id===b.dataset.agent);name=a?.name||db.mainAgentName||'Codex';description='AGENT · '+(a||db.connected?'연결됨':'연결되지 않음');status='남은 사용량'}const card=document.createElement('aside');card.className='coworker-hover-card';card.setAttribute('role','tooltip');card.innerHTML=`<div class="coworker-hover-head">${(b.querySelector('.helper-agent-portrait')||b.querySelector('.avatar')).outerHTML}<div><strong>${esc(name)}</strong><small>${esc(description||'HELPER')}</small></div></div><p>${esc(status||'함께할 작업을 기다리고 있어요.')}</p>`;if(b.dataset.helper){card.classList.add('helper-profile-card');card.onmouseleave=()=>{if(!card.classList.contains('participant-expanded-card'))card.remove()};card.innerHTML=helperProfileMarkup(helpers.find(h=>h.id===b.dataset.helper))}if(!b.dataset.helper){const agentId=b.dataset.agent||'main';const owned=helpers.filter(h=>(h.agentId||'main')===agentId).sort((a,b)=>Number(!!db.helperFavorites?.[b.id])-Number(!!db.helperFavorites?.[a.id]));card.classList.add('agent-hover-card');const remaining=db.extraAgents.find(a=>a.id===agentId)?.remainingUsagePercent??(agentId==='main'?db.agentRemainingUsagePercent:null);const known=typeof remaining==='number'&&Number.isFinite(remaining);const percent=known?Math.max(0,Math.min(100,remaining)):0;card.querySelector(':scope > p').outerHTML=`<div class="agent-remaining-usage"><span>남은 사용량</span><div class="agent-usage-row"><div class="agent-usage-track" role="progressbar" aria-label="남은 사용량" aria-valuemin="0" aria-valuemax="100" ${known?'aria-valuenow="'+percent+'"':'aria-valuetext="정보 없음"'}><span style="width:${percent}%"></span></div><span class="agent-usage-percent">${known?Math.round(percent)+'%':'—%'}</span></div></div>`;card.insertAdjacentHTML('beforeend',`<section class="agent-helper-list"><h4>HELPER (${owned.length})</h4><div>${owned.map(h=>`<div class="agent-helper-item" data-owned-helper="${h.id}">${avatar(h)}<span><strong>${esc(h.name)}</strong><small>${esc(h.shortDescription||h.description)}</small></span></div>`).join('')||'<p class="small">생성한 Helper가 없어요.</p>'}</div></section>`)}document.body.append(card);const rect=b.getBoundingClientRect(),side=document.querySelector('.home-side').getBoundingClientRect(),size=card.getBoundingClientRect();card.style.left=Math.max(8,Math.min(side.right+12,innerWidth-size.width-8))+'px';card.style.top=Math.max(b.dataset.helper?225:8,Math.min(rect.top,innerHeight-size.height-8))+'px'}

function dismissParticipantCard(){document.querySelector('.owned-helper-expanded:not(.is-pinned)')?.remove();document.querySelector('.agent-helper-hover-card')?.remove();document.querySelector('.active-chat-target')?.remove();document.querySelector('.home-side')?.classList.remove('has-active-chat');const card=document.querySelector('.participant-expanded-card:not(.is-pinned)');if(!card)return;card._sourceButton?.classList.remove('is-chat-open');card._sourceButton?.setAttribute('aria-expanded','false');card.remove();profileExpansionCard=null}
function collapseParticipantCard(card){document.querySelector('.owned-helper-expanded')?.remove();document.querySelector('.agent-helper-hover-card')?.remove();document.querySelector('.active-chat-target')?.remove();document.querySelector('.home-side')?.classList.remove('has-active-chat');card.querySelector('.expanded-card-body')?.remove();card.querySelector('[data-close]')?.remove();card._sourceButton?.classList.remove('is-chat-open');card._sourceButton?.setAttribute('aria-expanded','false');card.className='coworker-hover-card';card.setAttribute('role','tooltip');card.removeAttribute('aria-label');card.style.left='';card.style.top='';const b=card._sourceButton;card.remove();if(b.dataset.coworker)coworkerHover(b);else participantHover(b);const profile=document.querySelector('.coworker-hover-card');if(profile){profile._collapsedPinned=true;profile._sourceButton=b}profileExpansionCard=null}
document.addEventListener('click',e=>{const profile=document.querySelector('.coworker-hover-card');if(profile?._collapsedPinned&&!profile.contains(e.target)&&!profile._sourceButton?.contains(e.target))profile.remove();const card=document.querySelector('.participant-expanded-card:not(.is-pinned)');if(card&&!card._pinned&&!e.composedPath().includes(card)&&!card.contains(e.target)&&!card._sourceButton?.contains(e.target))dismissParticipantCard()});


function participantHeadingIcon(key){const paths={agent:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m7 9 3 3-3 3m6 0h4"/>',helper:'<path d="m12 3 2.6 5.4 5.9.9-4.3 4.2 1 5.9-5.2-2.8-5.2 2.8 1-5.9-4.3-4.2 5.9-.9Z"/>',coworker:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2m1-15a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v2"/>'};return '<svg class="participant-category-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[key]+'</svg>'}
function participantHasNews(key){return Object.entries(db.participantNews||{}).some(([id,n])=>id.startsWith(key+'-')&&n>0&&(key!=='coworker'||!db.coworkerMuted?.[id.slice('coworker-'.length)]&&!db.blockedCoworkers?.[id.slice('coworker-'.length)]))}
function participantNewsKey(b){return b.dataset.coworker!==undefined?'coworker-'+b.dataset.coworker:b.dataset.helper?'helper-'+b.dataset.helper:'agent-'+(b.dataset.agent||'main')}
function attachParticipantNews(){for(const b of $$('[data-coworker],#agent-home,[data-agent],.home-side [data-helper]')){const n=db.participantNews[participantNewsKey(b)]||0;if(!n||b.dataset.coworker!==undefined&&db.coworkerMuted?.[b.dataset.coworker])continue;const avatar=b.querySelector('.avatar');const wrap=document.createElement('span');wrap.className='participant-icon-wrap';avatar.before(wrap);wrap.append(avatar);if(b.dataset.coworker==='0')b.querySelector('.coworker-unread')?.remove();const badge=document.createElement('span');badge.className='participant-news-badge';badge.textContent=n;badge.setAttribute('aria-label','안 읽은 대화 '+n+'개');wrap.append(badge)}}
function readParticipantNews(b){const key=participantNewsKey(b);db.participantNews[key]=0;b.querySelector('.participant-news-badge')?.remove();const category=key.split('-')[0];if(!participantHasNews(category))document.querySelector('[data-participant-toggle="'+category+'"] .news-orb')?.remove();persist()}

