function openMyInfo(){db.userProfile??={name:'나',title:'',status:'',introduction:'',icon:'👤'};modal('내 정보',`<form id="my-info-form"><div class="my-info-identity"><div class="my-info-avatar-field"><div class="my-info-avatar-wrap"><div class="my-info-avatar" id="my-info-avatar" aria-hidden="true"></div><button type="button" class="my-info-edit-icon" id="my-info-edit-icon" aria-label="프로필 이미지 변경">✎</button></div></div><div class="my-info-primary"><div class="field"><label for="my-info-name">이름</label><input id="my-info-name" required maxlength="40"></div><div class="field"><label for="my-info-title">직함</label><input id="my-info-title" maxlength="60" placeholder="간단한 직함"></div></div></div><input id="my-info-image-file" type="file" accept="image/png,image/jpeg,image/webp" hidden><div class="field"><label for="my-info-status">상태 메시지</label><input id="my-info-status" maxlength="120" placeholder="지금 하고 있는 일을 알려 주세요."></div><div class="field"><label for="my-info-introduction">자기소개</label><textarea id="my-info-introduction" rows="4" maxlength="500" placeholder="자신을 소개해 주세요."></textarea></div><p class="small">프로토타입 · 이 브라우저에 저장됩니다.</p><div class="actions"><button type="submit" class="primary">저장</button></div></form>`,(root,close)=>{const profile=db.userProfile,preview=$('#my-info-avatar',root),file=$('#my-info-image-file',root);let avatarValue=profile.icon||'👤';const updateIcon=()=>preview.innerHTML=profileIconMarkup(avatarValue);updateIcon();$('#my-info-edit-icon',root).onclick=()=>file.click();file.onchange=async()=>{const picked=file.files?.[0];if(!picked)return;if(!['image/png','image/jpeg','image/webp'].includes(picked.type)||picked.size>5_000_000){toast('PNG, JPG, WebP 이미지(5MB 이하)를 선택해 주세요.');return}const url=URL.createObjectURL(picked);try{const img=new Image();img.src=url;await img.decode();const canvas=document.createElement('canvas');canvas.width=128;canvas.height=128;const context=canvas.getContext('2d'),side=Math.min(img.width,img.height);context.drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,128,128);avatarValue=canvas.toDataURL('image/webp',.85);updateIcon()}catch{toast('이미지를 읽을 수 없어요.')}finally{URL.revokeObjectURL(url);file.value=''}};$('#my-info-name',root).value=profile.name||'나';$('#my-info-title',root).value=profile.title||'';$('#my-info-status',root).value=profile.status||'';$('#my-info-introduction',root).value=profile.introduction||'';$('#my-info-form',root).onsubmit=e=>{e.preventDefault();const name=$('#my-info-name',root).value.trim();if(!name)return;db.userProfile={name,icon:avatarValue,title:$('#my-info-title',root).value.trim(),status:$('#my-info-status',root).value.trim(),introduction:$('#my-info-introduction',root).value.trim()};persist();$('.my-header-avatar').innerHTML=profileIconMarkup(db.userProfile.icon);close();toast('내 정보를 저장했어요.')}})}
function openAppSettings(){profileExpansionCard=null;modal('설정','<div class="app-settings-content"><h3>화면</h3><div class="field"><label for="settings-sidebar-width">사이드바 너비</label><div class="row"><input id="settings-sidebar-width" type="range" min="100" max="360" step="1" value="'+(db.participantSidebarWidth??144)+'"><output id="settings-sidebar-value">'+(db.participantSidebarWidth??144)+'px</output></div><small>너비에 따라 1~3열로 표시됩니다.</small></div></div>',root=>{root.querySelector('#settings-sidebar-width').oninput=e=>{const width=Number(e.target.value);db.participantSidebarWidth=width;const side=document.querySelector('.home-side');side.parentElement.style.setProperty('--participant-width',width+'px');side.style.setProperty('--participant-columns',width>=270?3:width>=180?2:1);side.querySelector('.participant-resizer').setAttribute('aria-valuenow',width);root.querySelector('output').textContent=width+'px';persist();if(page==='work')clampWindows()}})}

function setupBrowserTree(w){const pane=document.createElement('div');pane.className='browser-file-pane';const items=w.body.querySelector('.browser-items');items.before(pane);const tree=document.createElement('nav');tree.className='browser-folder-tree';tree.setAttribute('aria-label','폴더 계층');pane.append(tree,items);w.meta.closedFolders??=[];const render=()=>{tree.innerHTML='';const row=(id,name,depth,hasChildren)=>{const object=project.objects.find(o=>o.id===id);const line=document.createElement('div');line.className='folder-tree-row';line.style.setProperty('--depth',depth);if(hasChildren){const toggle=document.createElement('button');toggle.className='folder-tree-toggle';toggle.textContent=w.meta.closedFolders.includes(id)?'▸':'▾';toggle.setAttribute('aria-label',name+' 하위 항목');toggle.setAttribute('aria-expanded',String(!w.meta.closedFolders.includes(id)));toggle.onclick=()=>{w.meta.closedFolders=w.meta.closedFolders.includes(id)?w.meta.closedFolders.filter(x=>x!==id):[...w.meta.closedFolders,id];render();saveLayouts()};line.append(toggle)}else{const spacer=document.createElement('span');spacer.className='folder-tree-toggle';line.append(spacer)}const button=document.createElement('button');button.className='folder-tree-name';button.textContent=(object?.kind==='Category'?'▱ ':object?.icon?object.icon+' ':'')+name;button.title=name;button.dataset.treeId=id||'';button.classList.toggle('is-object-selected',!!id&&id===selected);button.oncontextmenu=e=>{e.preventDefault();e.stopPropagation();browserTreeCreateMenu(w,id,e)};button.setAttribute('aria-current',(w.meta.parent||null)===id?'location':'false');button.onclick=()=>{if(object&&object.kind!=='Category'){w.meta.parent=browserHierarchyParent(object)||w.meta.rootFolder||null;w.meta.query='';selected=id;renderBrowser(w);requestAnimationFrame(()=>{const target=$('[data-object=\"'+CSS.escape(id)+'\"]',w.body);target?.scrollIntoView({block:'nearest',inline:'nearest'});target?.focus({preventScroll:true})});return}w.meta.parent=id;w.meta.query='';selected=null;renderBrowser(w)};if(id&&object){button.draggable=true;button.ondragstart=e=>{e.stopPropagation();if(object.kind==='Category')startWorkspaceDrag(e,{kind:'tree',key:browserInstanceKey('tree',w.meta.group,id),group:w.meta.group,parentId:id,title:name+' 브라우저',width:502,height:348});else startObjectEditorDrag(e,object)};button.ondragend=endWorkspaceDrag}line.append(button);const working=browserFolderWorkers(id);if(working.length){const badges=document.createElement('span');badges.className='folder-workers';badges.innerHTML=working.length===1?browserWorker(working[0]):'<span class="worker-count" tabindex="0" aria-label="도우미 '+working.length+'명 작업 중">'+working.length+'<span class="worker-count-popover" role="tooltip">'+working.map(id=>browserWorker(id)).join('')+'</span></span>';line.append(badges);const count=badges.querySelector('.worker-count');if(count){let popup;const hide=()=>{popup?.remove();popup=null};const show=()=>{hide();popup=count.querySelector('.worker-count-popover').cloneNode(true);popup.classList.add('floating-worker-count');document.body.append(popup);const r=count.getBoundingClientRect();popup.style.left=Math.max(4,r.right-popup.offsetWidth)+'px';popup.style.top=Math.max(4,r.top-popup.offsetHeight-5)+'px'};count.onmouseenter=show;count.onmouseleave=hide;count.onfocus=show;count.onblur=hide;tree.addEventListener('scroll',hide);count.addEventListener('pointerdown',hide)}}tree.append(line)};const nodes=project.objects.filter(o=>o.group===w.meta.group&&(o.kind==='Category'||o.group==='concept'));const childOf=(o,parent)=>(browserHierarchyParent(o)||null)===parent;const rootId=w.meta.rootFolder||null,rootObject=project.objects.find(o=>o.id===rootId);row(rootId,rootObject?.name||(project.kind==='pack'?project.name:'ProjectPack'),0,nodes.some(o=>childOf(o,rootId)));const seen=new Set();const visit=(parent,depth)=>{nodes.filter(o=>childOf(o,parent)).forEach(o=>{if(seen.has(o.id))return;seen.add(o.id);const children=nodes.some(c=>childOf(c,o.id));row(o.id,o.name,depth,children);if(!w.meta.closedFolders.includes(o.id))visit(o.id,depth+1)})};if(!w.meta.closedFolders.includes(rootId))visit(rootId,1)};render()}
function updateBrowserTreeSelection(w){$$('.folder-tree-name',w.body).forEach(button=>button.classList.toggle('is-object-selected',!!selected&&button.dataset.treeId===selected))}
function browserTreeCreateMenu(w,id,e){
 const object=project.objects.find(o=>o.id===id),folder=object?.kind==='Category'||!object?object:null;
 const group=w.meta.group;
 const create=(kind,base=null)=>{w.meta.parent=folder?.id||w.meta.rootFolder||null;beginBrowserCreate(w,kind,base)};
 const entries=object&&object.kind!=='Category'?
  (group==='concept'?[['바리에이션 생성',()=>create('Concept',object)],['상세 편집',()=>openEditor(object.id)]]:[['상세 편집',()=>openEditor(object.id)]]):
  [['카테고리 생성',()=>create('Category')],[group==='concept'?'개념 생성':'새 '+groups[group]+' 생성',()=>create(group==='concept'?'Concept':group==='feature'?'Feature':'Module')]];
 contextMenu(e.clientX,e.clientY,entries);
}
function browserCompare(a,b,w){const order=w.meta.sort||'original';if(order==='name')return a.name.localeCompare(b.name,'ko',{numeric:true});if(order==='name-desc')return b.name.localeCompare(a.name,'ko',{numeric:true});if(order==='newest')return (b.createdAt||0)-(a.createdAt||0);return 0}
function browserCreateMenu(w,e){const entries=[['카테고리 생성',()=>beginBrowserCreate(w,'Category')],[w.meta.group==='concept'?'개념 생성':'새 '+groups[w.meta.group]+' 생성',()=>beginBrowserCreate(w,w.meta.group==='concept'?'Concept':w.meta.group==='feature'?'Feature':'Module')]];contextMenu(e.clientX,e.clientY,entries)}
function setupBrowserActions(w){const tools=w.body.querySelector('.browser-tools'),search=tools.querySelector('.search');search.style.minWidth='60px';const submit=document.createElement('button');submit.className='secondary';submit.textContent='검색';submit.setAttribute('aria-label','검색 확정');search.after(submit);const run=()=>{w.meta.query=search.value.trim();renderBrowserItems(w);saveLayouts()};submit.onclick=run;search.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();run()}};const sort=document.createElement('button');sort.className='secondary';sort.innerHTML='<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path d="M4 6h16M4 12h11M4 18h6" fill="none" stroke="currentColor" stroke-width="2"/></svg>';sort.title='정렬 방법';sort.setAttribute('aria-label','정렬 방법');tools.querySelector('[aria-label="새 의미 객체"]').before(sort);sort.onclick=e=>contextMenu(e.clientX,e.clientY,[['기본 순서','original'],['이름 오름차순','name'],['이름 내림차순','name-desc'],['최근 생성순','newest']].map(([label,value])=>[(w.meta.sort===value?'✓ ':'')+label,()=>{w.meta.sort=value;renderBrowserItems(w);saveLayouts()}]));const crumbs=w.body.querySelector('.crumbs');crumbs.innerHTML='';const path=[],seen=new Set();let item=project.objects.find(o=>o.id===w.meta.parent);while(item&&!seen.has(item.id)){seen.add(item.id);path.unshift(item);if(item.id===w.meta.rootFolder)break;item=project.objects.find(o=>o.id===browserHierarchyParent(item))};for(const o of [...(w.meta.rootFolder?[]:[{id:null,name:project.kind==='pack'?project.name:'ProjectPack'}]),...path]){if(crumbs.childNodes.length){const sep=document.createElement('span');sep.textContent='/';crumbs.append(sep)}const b=document.createElement('button');if(!o.id)b.dataset.root='';b.textContent=o.name;b.onclick=()=>{w.meta.parent=o.id;w.meta.query='';renderBrowser(w)};crumbs.append(b)}}
function beginBrowserCreate(w,kind,base=null){if(!w)return;w._cancelCreate?.();referenceTooltipCleanup?.();const owner=project;if(!base&&kind==='Concept'&&w.meta.group==='concept'){const scope=owner.objects.find(o=>o.id===w.meta.parent);if(scope&&scope.kind!=='Category')base=scope}const parent=base?base.parent:w.meta.parent;w.meta.parent=base?base.id:parent;w.meta.query='';renderBrowser(w);const root=w.body.querySelector('.browser-items');root.querySelector('.empty')?.remove();const draft=document.createElement('div');const mode=w.meta.density<=0?'Compact':w.meta.density>=100?'Data':'Preview';draft.className=(mode==='Data'?'object-data browser-data-row':mode==='Compact'?'object-row':'object-card concept-tile '+(kind==='Category'?'category-tile':'concept-file'))+' browser-create-draft';draft.innerHTML='<span class="obj-icon">'+(base?esc(base.icon):kind==='Category'?'▱':'◇')+'</span><input aria-label="새 항목 이름" maxlength="60"><small class="create-error" role="status"></small>';const input=draft.querySelector('input');input.setAttribute('aria-label','새 항목 이름');input.value=base?base.name+'Variant':kind==='Category'?'새 카테고리':'새 '+groups[w.meta.group];const listClass=mode==='Data'?'browser-data-list':mode==='Compact'?'compact-list':'object-grid';let grid=root.querySelector('.'+listClass);if(!grid){grid=document.createElement('div');grid.className=listClass;root.prepend(grid)}grid.append(draft);let done=false;const cancel=()=>{if(done)return;done=true;w._cancelCreate=null;renderBrowser(w)};w._cancelCreate=cancel;const commit=()=>{if(done)return;const name=input.value.trim();const error=!name?'이름을 입력하세요.':/[\/]/.test(name)?'이름에 /를 사용할 수 없어요.':owner.objects.some(o=>o.group===w.meta.group&&(o.parent||null)===(parent||null)&&o.name.toLowerCase()===name.toLowerCase())?'같은 이름이 있어요.':'';if(error){draft.querySelector('.create-error').textContent=error;input.setAttribute('aria-invalid','true');return}done=true;w._cancelCreate=null;const o={...(base?structuredClone(base):{description:'',owner:'ProjectPack',...(kind==='Concept'?{hp:100,speed:2,damage:10,range:1,cooldown:2}:{})}),id:uid(),name,kind,group:w.meta.group,parent:parent||null,icon:base?.icon||(kind==='Category'?'▱':'◇'),createdAt:Date.now(),helper:null};if(base)o.inherits=base.id;owner.objects.push(o);placeNamespaceObject(owner,o);selected=o.id;w.meta.parent=o.parent||w.meta.parent;persist();renderBrowser(w);refreshBrowserActions()};input.onkeydown=e=>{e.stopPropagation();if(e.key==='Escape'){e.preventDefault();cancel()}if(e.key==='Enter'){e.preventDefault();commit()}};input.onblur=()=>{if(input.isConnected)commit()};draft.scrollIntoView({block:'nearest'});input.focus();input.select()}

function browserWorker(id){const h=helpers.find(h=>h.id===id);return h?'<span class="collaborator worker-portrait" title="'+esc(h.name)+' 작업 중">'+avatar(h)+'</span>':''}
function browserFolderWorkers(id){return [...new Set(project.objects.filter(o=>{if(!o.helper)return false;if(id===null)return true;const seen=new Set();let node=o;while(node&&!seen.has(node.id)){if(node.id===id)return true;seen.add(node.id);node=project.objects.find(p=>p.id===node.parent)}return false}).map(o=>o.helper))]}
function browserExpand(o,w){return browserHasVariations(o)?'<button class="list-expand" data-enter-concept="'+o.id+'" aria-label="'+esc(o.name)+' 바리에이션으로 이동">▸</button>':''}
function browserDataItems(items,w){
 const labels={hp:'HP',speed:'이동속도',attack:'공격',drop:'드랍',description:'설명'};
 const hidden=new Set(['id','name','kind','group','parent','inherits','icon','helper','dirty','createdAt','owner']);
 const priority=['hp','speed','attack','drop','description'];
 const field=(o,key)=>{
  const value=o[key],label=labels[key]||key,type=typeof value==='number'?'number':typeof value==='boolean'?'checkbox':'text';
  const control=key==='owner'?'<span class="browser-data-value">'+esc(value)+'</span>':'<input data-obj="'+esc(o.id)+'" data-prop="'+esc(key)+'" aria-label="'+esc(o.name+' '+label)+'" type="'+type+'" '+(type==='number'?'step="any" ':'')+(type==='checkbox'?(value?'checked':''):'value="'+esc(typeof value==='object'?JSON.stringify(value):value)+'"')+'>';
  return '<label class="browser-data-field"><span>'+esc(label)+'</span>'+control+'</label>';
 };
 return '<div class="browser-data-list">'+items.map(o=>{
  const keys=Object.keys(o).filter(key=>!hidden.has(key)&&o[key]!==null&&o[key]!==undefined).sort((a,b)=>{const left=priority.indexOf(a),right=priority.indexOf(b);return (left<0?priority.length:left)-(right<0?priority.length:right)||a.localeCompare(b,'ko')});
  return '<article class="object-data browser-data-row '+(selected===o.id?'selected':'')+'" data-object="'+esc(o.id)+'" draggable="true" tabindex="0"><div class="browser-data-identity"><span class="obj-icon">'+esc(o.icon)+'</span>'+browserExpand(o,w)+'<button type="button" class="browser-data-name" data-inline-name="'+esc(o.id)+'" title="선택한 뒤 다시 누르면 이름 변경">'+esc(o.name)+'</button>'+browserWorker(o.helper)+'</div><div class="browser-data-fields">'+keys.map(key=>field(o,key)).join('')+'</div><button type="button" class="browser-data-edit" data-edit="'+esc(o.id)+'" aria-label="'+esc(o.name)+' 편집">⋯</button></article>';
 }).join('')+'</div>';
}
